//! The app env manifest (`<env>/share/hinteros/apps.json`, version 1; apps.md "The app env").
//!
//! Every profile's apps are a Nix profile whose current generation is an *app env*: a
//! `buildEnv` of the apps' packages plus this manifest, generated by the system repo's
//! `config.hinteros.appEnv.build ids`. The session daemon reads it instead of `session.toml`'s
//! `[[apps]]` (the `apps` entries have exactly the `[[apps]]` keys and are parsed by the session
//! daemon's own config code); the system service reads `ids` and `box` to track owners and box
//! features. Nothing in it comes from a caller.

use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

/// The manifest version this code reads.
pub const MANIFEST_VERSION: u32 = 1;

/// Where the manifest is, relative to the env.
pub const MANIFEST_PATH: &str = "share/hinteros/apps.json";

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Manifest {
    pub version: u32,
    /// The revision of the `hinteros` input the env was built against.
    #[serde(default)]
    pub system_rev: Option<String>,
    /// The catalog ids in the env, sorted.
    #[serde(default)]
    pub ids: Vec<String>,
    /// `apps.list` entries, with the keys of `session.toml`'s `[[apps]]` (parsed by the session
    /// daemon).
    #[serde(default)]
    pub apps: Vec<serde_json::Value>,
    /// Present when the env has Steam.
    #[serde(default)]
    pub steam: Option<SteamEntry>,
    /// Box features the env's apps need, sorted.
    #[serde(default, rename = "box")]
    pub box_features: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct SteamEntry {
    pub path: PathBuf,
}

#[derive(Debug, thiserror::Error)]
pub enum ManifestError {
    #[error("{0} not found")]
    Missing(PathBuf),
    #[error("reading {0}: {1}")]
    Io(PathBuf, std::io::Error),
    #[error("{0} is invalid: {1}")]
    Invalid(PathBuf, String),
}

impl Manifest {
    /// The manifest of the env at (or behind the link) `env`.
    pub fn load(env: &Path) -> Result<Self, ManifestError> {
        let path = env.join(MANIFEST_PATH);
        let bytes = match std::fs::read(&path) {
            Ok(b) => b,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
                return Err(ManifestError::Missing(path));
            }
            Err(e) => return Err(ManifestError::Io(path, e)),
        };
        Self::parse(&bytes).map_err(|m| ManifestError::Invalid(path, m))
    }

    pub fn parse(bytes: &[u8]) -> Result<Self, String> {
        let m: Manifest = serde_json::from_slice(bytes).map_err(|e| e.to_string())?;
        if m.version != MANIFEST_VERSION {
            return Err(format!(
                "manifest version {} (this daemon reads {MANIFEST_VERSION})",
                m.version
            ));
        }
        if let Some(bad) = m.ids.iter().find(|i| !crate::catalog::is_app_id(i)) {
            return Err(format!("bad id {bad:?}"));
        }
        if let Some(bad) = m
            .box_features
            .iter()
            .find(|f| !crate::catalog::is_box_feature(f))
        {
            return Err(format!("unknown box feature {bad:?}"));
        }
        if let Some(s) = &m.steam
            && !s.path.is_absolute()
        {
            return Err("steam.path must be absolute".into());
        }
        Ok(m)
    }

    /// An empty manifest (an env without apps).
    pub fn empty() -> Self {
        Self {
            version: MANIFEST_VERSION,
            system_rev: None,
            ids: Vec::new(),
            apps: Vec::new(),
            steam: None,
            box_features: Vec::new(),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_the_documented_example() {
        let m = Manifest::parse(
            br#"{
              "version": 1, "system_rev": "0f3c", "ids": ["jellyfin", "steam", "youtube"],
              "apps": [{"id": "jellyfin", "name": "Jellyfin", "kind": "native",
                        "command": ["/nix/store/x-jellyfin/bin/jellyfin-desktop"]}],
              "steam": {"path": "/nix/store/x-steam/bin/steam"},
              "box": ["graphics32", "steam-devices"], "future": 1
            }"#,
        )
        .unwrap();
        assert_eq!(m.ids, ["jellyfin", "steam", "youtube"]);
        assert_eq!(
            m.steam.unwrap().path,
            Path::new("/nix/store/x-steam/bin/steam")
        );
        assert_eq!(m.box_features, ["graphics32", "steam-devices"]);
        assert_eq!(m.apps.len(), 1);
        let empty = Manifest::parse(br#"{"version":1,"steam":null}"#).unwrap();
        assert!(empty.ids.is_empty() && empty.steam.is_none());
    }

    #[test]
    fn refuses_what_it_does_not_understand() {
        for bad in [
            r#"{"version":2}"#,
            r#"{}"#,
            r#"{"version":1,"ids":["../x"]}"#,
            r#"{"version":1,"box":["x86"]}"#,
            r#"{"version":1,"steam":{"path":"steam"}}"#,
            r#"[]"#,
        ] {
            assert!(Manifest::parse(bad.as_bytes()).is_err(), "{bad}");
        }
    }
}
